import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const l="/img/math-tree-planting-2.svg",g=JSON.parse('{"title":"小学奥数进阶：植树问题的特殊模型","description":"除了基础的直线植树，本文带你攻克封闭曲线植树、锯木头、爬楼梯等变式模型，理清“棵数”与“间隔数”的关系。","frontmatter":{"title":"小学奥数进阶：植树问题的特殊模型","date":"2026-02-08T11:00:00.000Z","categories":["数学"],"tags":["小学数学","奥数","植树问题"],"description":"除了基础的直线植树，本文带你攻克封闭曲线植树、锯木头、爬楼梯等变式模型，理清“棵数”与“间隔数”的关系。","cover":"/img/math-tree-planting-2.svg","top_img":"/img/math-tree-planting-2.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-tree-planting-2.md","filePath":"posts/primary-math-olympiad-tree-planting-2.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-tree-planting-2.md"};function e(o,a,p,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学奥数进阶-植树问题的特殊模型" tabindex="-1">小学奥数进阶：植树问题的特殊模型 <a class="header-anchor" href="#小学奥数进阶-植树问题的特殊模型" aria-label="Permalink to &quot;小学奥数进阶：植树问题的特殊模型&quot;">​</a></h1><h2 id="一、-核心逻辑回顾" tabindex="-1">一、 核心逻辑回顾 <a class="header-anchor" href="#一、-核心逻辑回顾" aria-label="Permalink to &quot;一、 核心逻辑回顾&quot;">​</a></h2><p>植树问题的灵魂在于理解：<strong>总长 = 间隔数 × 间距</strong>。</p><hr><h2 id="二、-三大特殊模型" tabindex="-1">二、 三大特殊模型 <a class="header-anchor" href="#二、-三大特殊模型" aria-label="Permalink to &quot;二、 三大特殊模型&quot;">​</a></h2><h3 id="_1-封闭曲线植树-圆、方阵周长" tabindex="-1">1. 封闭曲线植树（圆、方阵周长） <a class="header-anchor" href="#_1-封闭曲线植树-圆、方阵周长" aria-label="Permalink to &quot;1. 封闭曲线植树（圆、方阵周长）&quot;">​</a></h3><p><strong>模型</strong>：在圆形花坛或正方形池塘四周植树。</p><ul><li><strong>规律</strong>：首尾相接，最后的一棵树正好占了第一个间隔。</li><li><strong>公式</strong>：<strong>棵数 = 间隔数 = 总长 ÷ 间距</strong></li></ul><p><img src="'+l+'" alt="封闭曲线植树图解"></p><p><strong>例题</strong>：一个圆形池塘周长 120 米，每隔 6 米栽一棵柳树。一共要栽多少棵？</p><ul><li><strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>6</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120 \\div 6 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> 棵。</li></ul><h3 id="_2-爬楼梯问题" tabindex="-1">2. 爬楼梯问题 <a class="header-anchor" href="#_2-爬楼梯问题" aria-label="Permalink to &quot;2. 爬楼梯问题&quot;">​</a></h3><p><strong>模型</strong>：小明从 1 楼爬到 5 楼。</p><ul><li><strong>陷阱</strong>：1 楼是起点，不需要爬。从 1 楼到 5 楼实际上只爬了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">5 - 1 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 层楼梯。</li><li><strong>公式</strong>：<strong>层间数 = 目标楼层 - 起始楼层</strong></li><li><strong>例题</strong>：从 1 楼到 3 楼用了 20 秒。照这样计算，从 1 楼到 6 楼要用多少秒？ <ul><li><strong>1到3层</strong>：2 个间隔，每个间隔 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\div 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 秒。</li><li><strong>1到6层</strong>：5 个间隔，总时间 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">10 \\times 5 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span> 秒。</li></ul></li></ul><h3 id="_3-锯木头-敲钟问题" tabindex="-1">3. 锯木头/敲钟问题 <a class="header-anchor" href="#_3-锯木头-敲钟问题" aria-label="Permalink to &quot;3. 锯木头/敲钟问题&quot;">​</a></h3><p><strong>模型</strong>：把一根木头锯成 5 段。</p><ul><li><strong>规律</strong>：锯 1 次得 2 段，锯 2 次得 3 段。</li><li><strong>公式</strong>：<strong>次数 = 段数 - 1</strong></li><li><strong>例题</strong>：锯开一处要 4 分钟。把木头锯成 6 段要多少分钟？ <ul><li><strong>次数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">6 - 1 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 次。</li><li><strong>总时间</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">5 \\times 4 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> 分钟。</li></ul></li></ul><hr><h2 id="三、-进阶变式-二次植树" tabindex="-1">三、 进阶变式：二次植树 <a class="header-anchor" href="#三、-进阶变式-二次植树" aria-label="Permalink to &quot;三、 进阶变式：二次植树&quot;">​</a></h2><p><strong>例题</strong>：一条路长 100 米，原来每隔 5 米栽一棵树（两端都栽）。现在要改为每隔 4 米栽一棵。有多少棵树不需要移动？</p><ul><li><strong>分析</strong>：不移动的树，其位置必须既是 5 的倍数，又是 4 的倍数。</li><li><strong>找公倍数</strong>：5 和 4 的最小公倍数是 20。</li><li><strong>规律</strong>：每隔 20 米就有一棵树不需要动。</li><li><strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mn>0</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">100 \\div 20 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>（间隔数）。</li><li><strong>棵数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">5 + 1 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span> 棵（两端都算）。</li></ul><hr><h2 id="四、-总结提升" tabindex="-1">四、 总结提升 <a class="header-anchor" href="#四、-总结提升" aria-label="Permalink to &quot;四、 总结提升&quot;">​</a></h2><ol><li><strong>看清端点</strong>：是两端都种、一端种还是两端都不种？</li><li><strong>理解间隔</strong>：不管是锯木头还是爬楼梯，算的都是“间隔”。</li><li><strong>封闭图形</strong>：棵数永远等于间隔数。</li></ol><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>一个正方形操场，每边种 10 棵树（四个角都种）。一共种了多少棵？</li><li>时钟 4 点钟敲 4 下，6 秒钟敲完。那么 12 点钟敲 12 下，需要多少秒敲完？</li></ol><hr><p><em>提示：画个简易图，数数间隔就不会错！</em></p>',29)])])}const u=s(r,[["render",e]]);export{g as __pageData,u as default};
